using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
[InitializeOnLoad]public static class FinalAtlasGardenFinish{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",PrefabPath="Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/GardenUtilityAtlas",GroupName="City Atlas Gardens and Utilities";
static FinalAtlasGardenFinish(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalAtlasGardenFinish.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;var mode=File.ReadAllText("FinalAtlasGardenFinish.request").Trim();File.Delete("FinalAtlasGardenFinish.request");Run(mode=="water");}
static void Canopies(GameObject group){foreach(var f in group.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.StartsWith("GardenPlants_")||f.name.StartsWith("PortalIvy_"))){var mesh=f.sharedMesh;var p=mesh.vertices.ToList();var normals=mesh.normals.ToList();var uv=mesh.uv.ToList();var info=mesh.uv2.ToList();var colors=mesh.colors.ToList();var ids=mesh.triangles.ToList();int old=p.Count;var done=new HashSet<string>();for(int i=0;i<old;i+=4){if(info[i].x<4||info[i].x>8||colors[i].r>.01f||colors[i+2].r<.1f)continue;var bottom=(p[i]+p[i+1])*.5f;var top=(p[i+2]+p[i+3])*.5f;string key=Mathf.RoundToInt(bottom.x*100)+":"+Mathf.RoundToInt(bottom.z*100)+":"+info[i].x;if(!done.Add(key))continue;var right=(p[i+1]-p[i])*.43f;var across=Vector3.Cross(Vector3.up,right)*.92f;var center=Vector3.Lerp(bottom,top,.60f);int index=p.Count;p.AddRange(new[]{center-right-across,center+right-across,center+right+across,center-right+across});normals.AddRange(Enumerable.Repeat(Vector3.up,4));uv.AddRange(new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up});info.AddRange(Enumerable.Repeat(info[i],4));var color=colors[i];color.r=.65f;colors.AddRange(Enumerable.Repeat(color,4));ids.AddRange(new[]{index,index+1,index+2,index,index+2,index+3});}mesh.SetVertices(p);mesh.SetNormals(normals);mesh.SetUVs(0,uv);mesh.SetUVs(1,info);mesh.SetColors(colors);mesh.SetTriangles(ids,0);mesh.RecalculateBounds();var bounds=mesh.bounds;bounds.Expand(.25f);mesh.bounds=bounds;EditorUtility.SetDirty(mesh);}}
class State{public string name;public Mesh mesh;public bool active,enabled;}
static List<State> Merge(GameObject group){var all=group.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("UtilityCovers_")).ToArray();foreach(var chunk in all.GroupBy(r=>Mathf.FloorToInt(r.bounds.center.x/180)+"_"+Mathf.FloorToInt(r.bounds.center.z/180))){var members=chunk.ToArray();if(members.Length<2)continue;var mesh=new Mesh{name="CombinedUtility_"+chunk.Key,indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(members.Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=r.transform.localToWorldMatrix}).ToArray(),true,true,false);mesh.RecalculateBounds();string path=Out+"/Meshes/"+mesh.name+".asset";AssetDatabase.CreateAsset(mesh,path);var first=members[0];first.GetComponent<MeshFilter>().sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(first.GetComponent<MeshFilter>());foreach(var r in members.Skip(1)){r.enabled=false;r.gameObject.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(r);PrefabUtility.RecordPrefabInstancePropertyModifications(r.gameObject);}}return all.Select(r=>new State{name=r.name,mesh=r.GetComponent<MeshFilter>().sharedMesh,active=r.gameObject.activeSelf,enabled=r.enabled}).ToList();}
struct W{public Vector3 p;public Vector2 uv,uv1;public static W Lerp(W a,W b,float t)=>new W{p=Vector3.Lerp(a.p,b.p,t),uv=Vector2.Lerp(a.uv,b.uv,t),uv1=Vector2.Lerp(a.uv1,b.uv1,t)};}
static List<W> Clip(List<W> source,Func<Vector3,float> fn,bool inside){var result=new List<W>();if(source.Count<3)return result;for(int j=0;j<source.Count;j++){var a=source[j];var b=source[(j+1)%source.Count];float da=fn(a.p),db=fn(b.p);bool aa=inside?da>=0:da<=0,bb=inside?db>=0:db<=0;if(aa)result.Add(a);if(aa!=bb)result.Add(W.Lerp(a,b,da/(da-db)));}return result;}
static void Fan(List<W> poly,List<W> result){for(int i=1;i<poly.Count-1;i++){result.Add(poly[0]);result.Add(poly[i]);result.Add(poly[i+1]);}}
static void MaskWater(Scene scene,Bounds[] plots,StringBuilder log){var f=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Single(v=>v.name=="Water");var data=typeof(FinalSunkenUnderpasses).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f});var type=data.GetType();var p=(Vector3[])type.GetField("p").GetValue(data);var uv=(Vector2[])type.GetField("uv").GetValue(data);var uv1=(Vector2[])type.GetField("uv1").GetValue(data);var ids=(int[])type.GetField("ids").GetValue(data);var triangles=ids.Select(i=>new W{p=p[i],uv=uv[i],uv1=uv1[i]}).ToList();int before=triangles.Count/3;
foreach(var box in plots){var bounds=box;bounds.Expand(new Vector3(.4f,0,.4f));var output=new List<W>();for(int k=0;k<triangles.Count;k+=3){var poly=new List<W>{triangles[k],triangles[k+1],triangles[k+2]};foreach(var fn in new Func<Vector3,float>[] {v=>v.x-bounds.min.x,v=>bounds.max.x-v.x,v=>v.z-bounds.min.z,v=>bounds.max.z-v.z}){Fan(Clip(poly,fn,false),output);poly=Clip(poly,fn,true);if(poly.Count<3)break;}}triangles=output;}
var mesh=new Mesh{name="Water_Garden_Dry_Areas",indexFormat=IndexFormat.UInt32};mesh.SetVertices(triangles.Select(v=>f.transform.InverseTransformPoint(v.p)).ToList());mesh.SetNormals(Enumerable.Repeat(f.transform.InverseTransformDirection(Vector3.up).normalized,triangles.Count).ToList());mesh.SetUVs(0,triangles.Select(v=>v.uv).ToList());mesh.SetUVs(1,triangles.Select(v=>v.uv1).ToList());mesh.SetTriangles(Enumerable.Range(0,triangles.Count).ToArray(),0);mesh.RecalculateTangents();mesh.RecalculateBounds();string path=Out+"/Meshes/Water_Garden_Dry_Areas.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;EditorUtility.SetDirty(old);}else AssetDatabase.CreateAsset(mesh,path);f.sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(f);log.AppendLine("Existing city water masked beneath two garden plots; material retained; triangles "+before+" -> "+triangles.Count/3);}
static void UpdatePrefab(string path,List<State> states,bool main){var root=PrefabUtility.LoadPrefabContents(path);try{var group=main?root.transform.Find(GroupName):root.transform;var sceneRoot=SceneManager.GetSceneByPath(ScenePath).GetRootGameObjects().Single(g=>g.name=="Track Roads");var sceneGroup=sceneRoot.transform.Find(GroupName);foreach(var tree in sceneGroup.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Existing tree "))){var target=group.Find(AnimationUtility.CalculateTransformPath(tree,sceneGroup));if(target)target.localPosition=tree.localPosition;}foreach(var state in states){var t=group.Find(state.name);if(!t)throw new Exception("Prefab utility chunk missing "+state.name);t.GetComponent<MeshFilter>().sharedMesh=state.mesh;t.GetComponent<MeshRenderer>().enabled=state.enabled;t.gameObject.SetActive(state.active);}PrefabUtility.SaveAsPrefabAsset(root,path,out bool okay);if(!okay)throw new Exception("Prefab save failed");}finally{PrefabUtility.UnloadPrefabContents(root);}}
static void Run(bool water){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");EditorSceneManager.SaveScene(scene,"FinalEnvironmentRoadBackup/BeforeGardenFinish-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".unity",true);var groups=root.transform.Cast<Transform>().Where(t=>t.name==GroupName).ToArray();var group=(groups.FirstOrDefault(t=>!PrefabUtility.IsAddedGameObjectOverride(t.gameObject))??groups[0]).gameObject;foreach(var extra in groups.Where(t=>t.gameObject!=group))UnityEngine.Object.DestroyImmediate(extra.gameObject);
var mat=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City Garden Utility Atlas.mat");mat.SetTexture("_GrassDetail",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Oasis/3D/Texture/Road/Grass.jpg"));EditorUtility.SetDirty(mat);
var plots=new[]{"polySurface47","polySurface742"}.Select(name=>root.GetComponentsInChildren<MeshRenderer>(true).Single(r=>r.name==name)).ToArray();if(!File.Exists("FinalEnvironmentRoadReview/GardenFinishApplied.txt")){string backup="FinalEnvironmentRoadBackup/GardenDetailAssets-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);File.Copy(PrefabPath,backup+"/Before.prefab");foreach(var file in group.GetComponentsInChildren<MeshFilter>(true).Select(f=>AssetDatabase.GetAssetPath(f.sharedMesh)).Where(p=>p.StartsWith(Out+"/Meshes/")).Distinct())File.Copy(file,backup+"/"+Path.GetFileName(file));log.AppendLine("Detail mesh backups="+backup);foreach(var garden in group.transform.Cast<Transform>().Where(t=>t.name.StartsWith("Garden - "))){string name=garden.name.Substring(9);var plot=plots.Single(r=>r.name==name);foreach(var tree in garden.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Existing tree "))){var parts=tree.name.Split(' ');int sx=int.Parse(parts[2]),sz=int.Parse(parts[3]);var rs=tree.GetComponentsInChildren<Renderer>();var bounds=rs[0].bounds;foreach(var r in rs.Skip(1))bounds.Encapsulate(r.bounds);var target=new Vector3(Mathf.Lerp(plot.bounds.min.x,plot.bounds.max.x,.5f+sx*.33f),bounds.center.y,Mathf.Lerp(plot.bounds.min.z,plot.bounds.max.z,.5f+sz*.23f));tree.position+=target-bounds.center;PrefabUtility.RecordPrefabInstancePropertyModifications(tree);}}Canopies(group);var states=Merge(group);UpdatePrefab(PrefabPath,states,true);UpdatePrefab(Out+"/City Atlas Gardens and Utilities.prefab",states,false);File.WriteAllText("FinalEnvironmentRoadReview/GardenFinishApplied.txt","canopies and utility merge applied");}
if(water)MaskWater(scene,plots.Select(r=>r.bounds).ToArray(),log);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var current=root.transform.Cast<Transform>().Where(t=>t.name==GroupName).ToArray();if(current.Length!=1)throw new Exception("Duplicate group remains");group=current[0].gameObject;int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);int activeChunks=group.GetComponentsInChildren<MeshRenderer>(true).Count(r=>r.name.StartsWith("UtilityCovers_")&&r.enabled&&r.gameObject.activeInHierarchy);log.AppendLine("SUCCESS: one detail group; utility batches visible="+activeChunks+"; top foliage cards added; existing grass-detail texture reused; no new texture or material; shader errors=0; scene and both prefabs updated.");File.WriteAllText("FinalAtlasGardens.request","preview");File.WriteAllText("FinalSunkenUnderpasses.request","finalcheck");
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/GardenFinishReport.txt",log.ToString());}}
